package com.bani.medreminder;
import android.app.*; import android.content.*; import android.os.Bundle; import android.view.WindowManager; import android.widget.*; import java.text.SimpleDateFormat; import java.util.*;
public class AlarmActivity extends Activity { long medId;Db db; @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_alarm);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON|WindowManager.LayoutParams.FLAG_SHOW_WHEN_LOCKED|WindowManager.LayoutParams.FLAG_TURN_SCREEN_ON);medId=getIntent().getLongExtra("medId",-1);db=new Db(this);Med m=db.get(medId);if(m==null){finish();return;}((TextView)findViewById(R.id.alarmTitle)).setText("⚠️ وقت مصرف: "+m.name);((TextView)findViewById(R.id.alarmDetail)).setText((m.dose==null?"":m.dose)+"\nموجودی: "+m.stock+" عدد");findViewById(R.id.taken).setOnClickListener(v->{String d=new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date());db.markTaken(medId,d);stopService(new Intent(this,AlarmService.class));Med after=db.get(medId);if(after!=null&&after.stock<=3)Toast.makeText(this,"موجودی "+after.name+" رو به اتمام است: "+after.stock,Toast.LENGTH_LONG).show();finish();});findViewById(R.id.snooze).setOnClickListener(v->{stopService(new Intent(this,AlarmService.class));AlarmScheduler.scheduleSnooze(this,medId,5*60*1000L);finish();}); } }
